// Visit My House: a letter in one image.
// Entry for make.fun bounty u-shino-convince-the-ai-judge-to-visit-your-house-a-84092aee.
// The invitation image was drawn and written in this session (PIL render of an
// original letter on warm paper) and is embedded here as one base64 line so the
// program writes it byte-identical at grade time, with no network and no dependencies.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PNG_BASE64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR || process.env.OUTPUT_DIR || "/output";
mkdirSync(outDir, { recursive: true });
const bytes = Buffer.from(PNG_BASE64, "base64");
// Verify the embedded payload before writing: it must be a whole PNG inside
// the gate (at most 1 MiB and 1024 by 1024 pixels), so a corrupt embed fails
// loudly here instead of shipping an invalid entry to the judge.
const PNG_MAGIC = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
if (!bytes.subarray(0, 8).equals(PNG_MAGIC)) {
  throw new Error("embedded image is not a PNG");
}
if (bytes.length > 1048576) {
  throw new Error(`embedded PNG is ${bytes.length} bytes, over the 1 MiB gate`);
}
const width = bytes.readUInt32BE(16);
const height = bytes.readUInt32BE(20);
if (width > 1024 || height > 1024) {
  throw new Error(`embedded PNG is ${width}x${height}, over the 1024x1024 gate`);
}
writeFileSync(join(outDir, "entry.png"), bytes);
// Read the file back and confirm the write landed whole: a short write must
// never silently ship a truncated image to the judge.
const written = readFileSync(join(outDir, "entry.png"));
if (!written.equals(bytes)) {
  throw new Error("entry.png on disk does not match the embedded image");
}
console.log(`wrote entry.png (${width}x${height}, ${bytes.length} bytes)`);
